// B10 — Lifetime & Next Action: RFV scoring + tier + milestone detection
const d = $('Edit Fields').item.json;
const existing = $input.all();
const now = new Date();

const purchaseAmount = parseFloat(d['purchaseAmount']) || 0;

let totalPurchases = 1;
let totalSpend = purchaseAmount;
let firstPurchaseDate = d['purchaseDate'];
let previousTier = 'None';
let isNewCustomer = true;
let recentAmounts = [purchaseAmount];

if (existing.length > 0 && existing[0].json['Customer Name']) {
  const rec = existing[0].json;
  isNewCustomer = false;
  totalPurchases = (parseInt(rec['Total Purchases']) || 0) + 1;
  totalSpend = (parseFloat(rec['Total Spend']) || 0) + purchaseAmount;
  firstPurchaseDate = rec['First Purchase Date'] || d['purchaseDate'];
  previousTier = rec['Tier'] || 'None';
  // Track last 3 purchase amounts as comma-separated string
  const prev = (rec['Recent Amounts'] || '').split(',').map(s => parseFloat(s)).filter(n => !isNaN(n));
  recentAmounts = [purchaseAmount, ...prev].slice(0, 3);
}

const avgOrderValue = totalSpend / totalPurchases;
const lifetimeValue = totalSpend;

// Tier assignment
let tier = 'Bronze';
let vipFlag = false;
if (lifetimeValue >= 50000) { tier = 'VIP'; vipFlag = true; }
else if (lifetimeValue >= 20000) { tier = 'Gold'; }
else if (lifetimeValue >= 8000) { tier = 'Silver'; }

// Tier change detection
const tierOrder = { 'None': 0, 'Bronze': 1, 'Silver': 2, 'Gold': 3, 'VIP': 4 };
const tierUpgraded = tierOrder[tier] > tierOrder[previousTier];
const tierChanged = tier !== previousTier && previousTier !== 'None';

// Milestone detection — celebrate round-number purchases
const milestones = [5, 10, 25, 50, 100];
const isMilestone = milestones.includes(totalPurchases);
const milestoneNumber = isMilestone ? totalPurchases : 0;

// Spend trajectory — comparing latest vs avg of previous
let trajectory = 'stable';
if (recentAmounts.length >= 2) {
  const latest = recentAmounts[0];
  const prevAvg = recentAmounts.slice(1).reduce((a,b) => a+b, 0) / (recentAmounts.length - 1);
  if (latest > prevAvg * 1.25) trajectory = 'up';
  else if (latest < prevAvg * 0.7) trajectory = 'down';
}

// Should we celebrate? Tier upgrade OR milestone
const shouldCelebrate = tierUpgraded || isMilestone;

const formatRand = n => 'R' + n.toLocaleString('en-ZA', { minimumFractionDigits: 2 });
const firstName = (d['customerName'] || 'there').split(' ')[0];

// Build celebration reason for AI prompt
let celebrationReason = '';
if (tierUpgraded && isMilestone) {
  celebrationReason = `Reached ${totalPurchases} purchases AND just upgraded to ${tier} tier`;
} else if (tierUpgraded) {
  celebrationReason = `Just upgraded to ${tier} tier (was ${previousTier})`;
} else if (isMilestone) {
  celebrationReason = `Just reached ${totalPurchases} total purchases — a milestone`;
}

return [{
  json: {
    ...d,
    totalPurchases, totalSpend, avgOrderValue, lifetimeValue,
    tier, vipFlag, tierChanged, tierUpgraded, previousTier,
    isNewCustomer, isMilestone, milestoneNumber, shouldCelebrate,
    celebrationReason,
    firstPurchaseDate,
    recentAmounts: recentAmounts.join(','),
    trajectory,
    firstName,
    lifetimeValueFormatted: formatRand(lifetimeValue),
    avgOrderFormatted: formatRand(avgOrderValue),
    purchaseAmountFormatted: formatRand(purchaseAmount),
    runAt: $now.setZone('Africa/Johannesburg').toFormat('yyyy-MM-dd HH:mm:ss')
  }
}];

