// B10 — Top 5 Next Actions: RFV scoring + per-customer recommendation
const rows = $input.all();
const now = new Date();

if (!rows.length) {
  return [{ json: { hasData: false, summary: 'No customer data to analyse this week.' } }];
}

const customers = rows
  .map(r => r.json)
  .filter(r => r['Customer Email'] && r['Customer Name']);

if (!customers.length) {
  return [{ json: { hasData: false, summary: 'No valid customer records found.' } }];
}

const formatRand = n => 'R' + n.toLocaleString('en-ZA', { minimumFractionDigits: 2 });

// Calculate RFV score for each customer
const scored = customers.map(c => {
  const ltv = parseFloat(c['Lifetime Value']) || 0;
  const purchases = parseInt(c['Total Purchases']) || 0;
  const lastPurchase = c['Last Purchase Date'] ? new Date(c['Last Purchase Date']) : null;
  const daysSinceLast = lastPurchase && !isNaN(lastPurchase.getTime())
    ? Math.floor((now - lastPurchase) / 86400000) : 999;
  const tier = c['Tier'] || 'Bronze';
  const trajectory = c['Trajectory'] || 'stable';

  // Recency score (lower days = higher score, capped at 90 days)
  const recencyScore = Math.max(0, 100 - (daysSinceLast / 90 * 100));
  // Frequency score (more purchases = higher score)
  const freqScore = Math.min(100, purchases * 5);
  // Value score (LTV normalized)
  const valueScore = Math.min(100, ltv / 500);

  // Weighted RFV — Value matters most
  const rfv = (recencyScore * 0.25) + (freqScore * 0.25) + (valueScore * 0.50);

  // Determine next action recommendation
  let action = 'Keep nurturing';
  let actionReason = '';

  if (tier === 'VIP' && daysSinceLast > 30) {
    action = 'White-glove check-in';
    actionReason = `VIP customer silent for ${daysSinceLast} days. Personal call or hand-written note.`;
  } else if (tier === 'VIP' && trajectory === 'up') {
    action = 'Premium upsell';
    actionReason = `VIP spending trending up — offer your highest-value product or experience.`;
  } else if (tier === 'Gold' && trajectory === 'up') {
    action = 'Tier-up nudge to VIP';
    actionReason = `Gold customer trending up — one big purchase pushes them to VIP. Suggest premium offer.`;
  } else if (tier === 'Bronze' && purchases >= 3 && trajectory === 'up') {
    action = 'Tier-up offer to Silver';
    actionReason = `Loyal Bronze on the rise. A bundled offer could push them to Silver.`;
  } else if (daysSinceLast > 60 && tier !== 'Bronze') {
    action = 'Win-back attempt';
    actionReason = `${tier} customer hasn't bought in ${daysSinceLast} days. Personal re-engagement before they churn.`;
  } else if (trajectory === 'down') {
    action = 'Trajectory check-in';
    actionReason = `Spending dropping. Friendly check-in to find out what changed.`;
  } else if (purchases >= 5 && daysSinceLast < 14) {
    action = 'Ask for a referral';
    actionReason = `Loyal, recent buyer. Best moment to ask for a referral or review.`;
  }

  return {
    name: c['Customer Name'], email: c['Customer Email'],
    tier, ltv, ltvFormatted: formatRand(ltv),
    purchases, daysSinceLast, trajectory,
    rfv: rfv.toFixed(1), action, actionReason,
    lastProduct: c['Last Product'] || 'unknown'
  };
});

// Sort by RFV, take top 5
scored.sort((a, b) => parseFloat(b.rfv) - parseFloat(a.rfv));
const top5 = scored.slice(0, 5);

// Build summary for AI
const top5Summary = top5.map((c, i) =>
  `${i+1}. ${c.name} (${c.tier}, ${c.purchases} purchases, ${c.ltvFormatted} LTV, ${c.daysSinceLast}d since last) — ACTION: ${c.action}. ${c.actionReason}`
).join('\n');

const byTier = {
  VIP: scored.filter(c => c.tier === 'VIP').length,
  Gold: scored.filter(c => c.tier === 'Gold').length,
  Silver: scored.filter(c => c.tier === 'Silver').length,
  Bronze: scored.filter(c => c.tier === 'Bronze').length
};

const summary = `Total customers: ${customers.length}. Tier breakdown: VIP ${byTier.VIP}, Gold ${byTier.Gold}, Silver ${byTier.Silver}, Bronze ${byTier.Bronze}. Top 5 by RFV score this week:\n${top5Summary}`;

return [{
  json: {
    hasData: true,
    totalCustomers: customers.length,
    byTier,
    top5,
    top5Summary,
    summary,
    reportDate: now.toLocaleDateString('en-ZA', { timeZone: 'Africa/Johannesburg' })
  }
}];

