// B10 — Monthly LTV Aggregator
const rows = $input.all();
if (!rows.length) return [{ json: { hasData: false } }];

const customers = rows.map(r => r.json).filter(r => r['Customer Email']);
if (!customers.length) return [{ json: { hasData: false } }];

const formatRand = n => 'R' + n.toLocaleString('en-ZA', { minimumFractionDigits: 2 });

const total = customers.length;
const vipCount = customers.filter(r => r['Tier'] === 'VIP').length;
const goldCount = customers.filter(r => r['Tier'] === 'Gold').length;
const silverCount = customers.filter(r => r['Tier'] === 'Silver').length;
const bronzeCount = customers.filter(r => r['Tier'] === 'Bronze').length;

const totalLTV = customers.reduce((acc, r) => acc + (parseFloat(r['Lifetime Value']) || 0), 0);
const avgLTV = totalLTV / total;

// Top customer by LTV
const sorted = [...customers].sort((a,b) => (parseFloat(b['Lifetime Value']) || 0) - (parseFloat(a['Lifetime Value']) || 0));
const top = sorted[0] || {};
const topName = top['Customer Name'] || 'N/A';
const topLTV = formatRand(parseFloat(top['Lifetime Value']) || 0);

// Trajectory breakdown
const trajUp = customers.filter(r => r['Trajectory'] === 'up').length;
const trajDown = customers.filter(r => r['Trajectory'] === 'down').length;
const trajStable = customers.filter(r => r['Trajectory'] === 'stable' || !r['Trajectory']).length;

const monthName = $now.setZone('Africa/Johannesburg').toFormat('yyyy-MM-dd HH:mm:ss');
const year = new Date().getFullYear();

const summary = [
  'Total customers: ' + total,
  'Tier: VIP ' + vipCount + ', Gold ' + goldCount + ', Silver ' + silverCount + ', Bronze ' + bronzeCount,
  'Total LTV: ' + formatRand(totalLTV),
  'Average LTV: ' + formatRand(avgLTV),
  'Top customer: ' + topName + ' at ' + topLTV,
  'Trajectory: ' + trajUp + ' rising, ' + trajStable + ' stable, ' + trajDown + ' declining'
].join('. ');

return [{
  json: {
    hasData: true, total, vipCount, goldCount, silverCount, bronzeCount,
    totalLTV: formatRand(totalLTV), avgLTV: formatRand(avgLTV),
    topName, topLTV, trajUp, trajDown, trajStable,
    monthName, year, summary
  }
}];

